scripts.source:
matches() {
    grep -F "$needle" "$1"
}
review() {
    local needle="$1"
    printf 'Topic: %s\n' "$needle"
    matches "$2"
}
needle=$SUMMARY
review "$1" "$3"
review "$2" "$3"
printf 'Review: %s\n' "$needle"

scripts.example_source:
tone='quiet'
announce() {
    printf 'Tone: %s\n' "$tone"
}
visit() {
    local tone='loud'
    announce
}
visit
announce

if test "$#" -ne 2 || test -z "$2"; then
    printf 'Need VIEW TITLE\n' >&2
    exit 2
fi
case "$1" in
    quick|summary) printf 'Loan %s: %s\n' "$2" "$NOTE" ;;
    detail) printf 'Loan %s\n' "$2"; cat museum.txt ;;
    *) printf 'Unknown view\n' >&2; exit 2 ;;
esac

mode=$1
prepare() {
    while read -r item || test -n "$item"; do
        case "$item" in
            ''|wait:*) : ;;
            ok:?*) printf '%s\n' "$item" ;;
            *) printf 'Bad loan: %s\n' "$item" >&2; return 1 ;;
        esac
    done < "$1"
    return 0
}
text=$(prepare "$2")
status=$?
if test "$status" -ne 0; then exit "$status"; fi
case "$mode" in
    review) printf 'Review <%s>\n' "$text" ;;
    save)
        printf '%s' "$text" > docket.txt
        printf 'Saved from %s\n' "$2" >> 'loan ledger.txt'
        printf 'Saved <%s>\n' "$text"
        ;;
    *) printf 'Unknown action\n' >&2; exit 2 ;;
esac

LC_ALL=C
for action in "$@"; do
 case "$action" in
  titles) command=(sort -- -catalogue) ;;
  shelves) command=(cut -s -d ':' -f 2 -- museum-locations.txt) ;;
  *) printf 'Unknown museum action\n' >&2; exit 2 ;;
 esac
 "${command[@]}"
done

